window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c50b10f04fdc0e9"]={"versions": [{"id": "FIG-1c50b10f04fdc0e9", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Modellierungsdiagramm (Strukturdiagramm der Hardware-Ressourcenbeschreibung) im Kontext des AUTOSAR ECU Resource Template (<code>AUTOSAR_ResourceTemplateECU</code>). Es visualisiert eine ungültige Konfiguration bezüglich der Verknüpfung von Hardware-Verbindungen (<code>HW Connection</code>) mit Hardware-Ports (<code>HW Port</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>HW Container</strong>: Umfassender Container für Hardware-Elemente und deren Verbindungen.</li>\n<li><strong>HW Element 1</strong>: Hardware-Element mit drei Ports.</li>\n<li><strong>HW Element 2</strong>: Hardware-Element mit einem Port.</li>\n<li><strong>HW Element 3</strong>: Hardware-Element mit einem Port.</li>\n<li><strong>Ports (HW Port)</strong>: Durch kleine Rechtecke an den Kanten der HW-Elemente dargestellte Schnittstellen.</li>\n<li><strong>Conn1, Conn2</strong>: Hardware-Verbindungen (<code>HW Connection</code>), die jeweils vom mittleren Port von <code>HW Element 1</code> zum Port von <code>HW Element 2</code> bzw. zum Port von <code>HW Element 3</code> führen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungsbeispiel ohne Laufzeit-Sequenzablauf. Es demonstriert die statische Topologie bzw. Verknüpfung mehrerer logischer Hardware-Verbindungen an einem gemeinsamen Port.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht ein normatives Modellierungsverbot (Anti-Pattern / unzulässige Modellierungskonfiguration): Mehrere Hardware-Verbindungen (<code>Conn1</code> und <code>Conn2</code>) dürfen nicht demselben Hardware-Port (hier dem mittleren Port von <code>HW Element 1</code>) zugeordnet werden. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass pro HW-Port höchstens eine HW-Verbindung angebunden ist.</p>"}, {"id": "FIG-cb04363c9f295e53", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Modellierungsdiagramm (Strukturdiagramm der Hardware-Ressourcenbeschreibung) im Kontext des AUTOSAR ECU Resource Template (<code>AUTOSAR_ResourceTemplateECU</code>). Es visualisiert eine ungültige Konfiguration bezüglich der Verknüpfung von Hardware-Verbindungen (<code>HW Connection</code>) mit Hardware-Ports (<code>HW Port</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>HW Container</strong>: Umfassender Container für Hardware-Elemente und deren Verbindungen.</li>\n<li><strong>HW Element 1</strong>: Hardware-Element mit drei Ports.</li>\n<li><strong>HW Element 2</strong>: Hardware-Element mit einem Port.</li>\n<li><strong>HW Element 3</strong>: Hardware-Element mit einem Port.</li>\n<li><strong>Ports (HW Port)</strong>: Durch kleine Rechtecke an den Kanten der HW-Elemente dargestellte Schnittstellen.</li>\n<li><strong>Conn1, Conn2</strong>: Hardware-Verbindungen (<code>HW Connection</code>), die jeweils vom mittleren Port von <code>HW Element 1</code> zum Port von <code>HW Element 2</code> bzw. zum Port von <code>HW Element 3</code> führen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungsbeispiel ohne Laufzeit-Sequenzablauf. Es demonstriert die statische Topologie bzw. Verknüpfung mehrerer logischer Hardware-Verbindungen an einem gemeinsamen Port.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht ein normatives Modellierungsverbot (Anti-Pattern / unzulässige Modellierungskonfiguration): Mehrere Hardware-Verbindungen (<code>Conn1</code> und <code>Conn2</code>) dürfen nicht demselben Hardware-Port (hier dem mittleren Port von <code>HW Element 1</code>) zugeordnet werden. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass pro HW-Port höchstens eine HW-Verbindung angebunden ist.</p>"}], "trans": [{"from": "FIG-1c50b10f04fdc0e9", "to": "FIG-cb04363c9f295e53", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
